var a=[{title:`Schemat RAMP`,text:`RAMP to skrót od Raise (podnieś), Activate (aktywuj), Mobilize (uruchom ruchomość) i Potentiate (przygotuj do mocy). Podnieś temperaturę ciała i oddech łatwą aktywnością, obudź mięśnie, których użyjesz, kontrolowanymi ruchami, przejdź przez potrzebne zakresy, a potem przećwicz ćwiczenie z stopniowo wyższym wysiłkiem, który nadal zostawia Cię świeżym. Fazy mogą się nakładać. Nie muszą być czterema długimi blokami.`},{title:`Pięć do dziesięciu minut na start`,text:`Zacznij od lekkiego marszu lub jazdy na rowerze. Dodaj kontrolowane przysiady z masą ciała, zawiasy biodrowe, krążenia ramion lub inne ćwiczenia pasujące do treningu. Przed ciężkim ćwiczeniem wykonaj jedną lub więcej lżejszych serii narastających. Przed interwałami zacznij od łatwiejszych wersji tego samego ruchu zamiast od razu wchodzić w sprint.`},{title:`Rozgrzewka do zadania`,text:`Wyciskanie nad głową może wymagać pewnego ruchu barków i lekkiej serii wyciskania. Bieg może wymagać łatwego truchtu i kilku stopniowych przyspieszeń. Ciężka lub techniczna praca często wymaga większego przygotowania niż spokojny spacer. Celem jest poczucie gotowości, a rozbudowana rozgrzewka, która Cię męczy, mija się z tym celem.`},{title:`Gdzie pasuje rozciąganie`,text:`Długie bierne rozciąganie tuż przed dynamiczną aktywnością może w niektórych warunkach chwilowo obniżyć wydajność. Krótkie, wygodne rozciąganie nie jest automatycznie szkodliwe, ale dynamiczna ruchomość i stopniowe ćwiczenie zwykle liczą się bardziej tuż przed pracą siłową, sprintem lub skakaniem. Nigdy nie rozciągaj się przez ból, by osiągnąć jakąś dowolną głębokość.`},{title:`Złożenie całości`,text:`Zbuduj rozgrzewkę z ruchów dzisiejszego treningu, Twojego poziomu umiejętności i przestrzeni: kilka minut łatwej aktywności, potem lekkie wersje pierwszego ćwiczenia, z większym przygotowaniem, gdy praca jest cięższa lub szybsza. Wlicz rozgrzewkę w czas treningu.`}];var o=[{label:`ACE 2026: praktyczne wskazówki dotyczące rozciągania`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Biblioteka ćwiczeń ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};